// Spec 1126 (order 5) — provenance headers on generated state files.
//
// Every state file the builder freshly emits must start with the
// `// GENERATED BY zuraffa zfa state create — DO NOT EDIT BY HAND.`
// block, carrying the generator version and a regeneration hint, so
// humans and `zfa proof check`-style audits can tell generated state
// classes from hand-written ones (the datasource/provider A+
// precedent, spec #1131 order 5 + spec #979).
//
// Determinism gate: the header must NOT carry run-varying bytes (a
// wall-clock timestamp) — the byte-identity gates
// (state_snapshot_test, state_make_drift_test) require
// `zfa state create` ≡ `zfa make --state` ≡ last regeneration, run
// after run. The run timestamp provenance lives in the receipt's `at`
// field instead (machine-readable, sha256-bound).
library;

import 'dart:io';

import 'package:path/path.dart' as p;
import 'package:test/test.dart';
import 'package:zuraffa/src/models/generator_config.dart';
import 'package:zuraffa/src/plugins/state/builders/state_builder.dart';
import 'package:zuraffa/src/plugins/state/state_provenance.dart';
import 'package:zuraffa/src/version.dart';

void main() {
  late Directory workspace;

  setUp(() async {
    workspace = await Directory.systemTemp.createTemp('zfa_state_prov_');
  });

  tearDown(() async {
    if (workspace.existsSync()) {
      try {
        await workspace.delete(recursive: true);
      } on FileSystemException {
        // Best-effort cleanup.
      }
    }
  });

  GeneratorConfig config(String outputDir, {bool noEntity = false}) =>
      GeneratorConfig(
        name: 'Product',
        methods: noEntity ? const [] : const ['get', 'getList'],
        generateState: true,
        outputDir: outputDir,
      );

  test('the header factory carries the marker, the version and the hint', () {
    final header = StateProvenance.headerFor('Product');
    expect(
      header,
      startsWith(
        '// GENERATED BY zuraffa zfa state create — '
        'DO NOT EDIT BY HAND.',
      ),
      reason: 'the marker line the issue pins',
    );
    expect(header, contains(version), reason: 'the generator version');
    expect(
      header,
      contains('zfa state create --name Product'),
      reason: 'the regeneration hint names the exact command',
    );
  });

  test('every generated state file starts with the provenance header '
      '(entity mode)', () async {
    final builder = StateBuilder(
      outputDir: p.join(workspace.path, 'lib', 'src'),
    );
    final file = await builder.generate(
      config(p.join(workspace.path, 'lib', 'src')),
    );

    final onDisk = File(file.path);
    expect(onDisk.existsSync(), isTrue);
    expect(
      onDisk.readAsStringSync(),
      startsWith(StateProvenance.generatedHeader),
      reason: '${file.path} must carry the provenance header',
    );
  });

  test('the header is stamped in the custom/no-entity branch too', () async {
    final out = p.join(workspace.path, 'lib', 'src');
    final builder = StateBuilder(outputDir: out);
    final file = await builder.generate(config(out, noEntity: true));

    final onDisk = File(file.path);
    expect(onDisk.existsSync(), isTrue);
    expect(
      onDisk.readAsStringSync(),
      startsWith(StateProvenance.generatedHeader),
      reason:
          'both emission branches stamp the header (custom/orchestrator '
          'and entity)',
    );
  });

  test(
    'the header is deterministic across runs (no wall-clock bytes)',
    () async {
      final out = p.join(workspace.path, 'lib', 'src');
      final first = await StateBuilder(outputDir: out).generate(config(out));
      final firstBytes = File(first.path).readAsStringSync();

      // A second builder, a later instant, same config → same bytes.
      await Future<void>.delayed(const Duration(milliseconds: 5));
      final second = await StateBuilder(outputDir: out).generate(config(out));
      final secondBytes = File(second.path).readAsStringSync();

      expect(
        secondBytes,
        firstBytes,
        reason:
            'run-varying header bytes would permanently break the snapshot '
            'and make-drift byte-identity gates',
      );
    },
  );
}
